set -euo pipefail
shopt -s nullglob
tarballs=("$LYRA_PACKED_MIGRATION_ARTIFACTS"/packages/aceshooting-lyra-ui-*.tgz)
if [[ "${#tarballs[@]}" -ne 1 ]]; then
  echo "::error::Expected exactly one preserved Lyra UI tarball"
  exit 1
fi
LYRA_PEER_TARBALL="${tarballs[0]}" node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { basename } from 'node:path';
const tarball = process.env.LYRA_PEER_TARBALL;
const receipt = JSON.parse(readFileSync(`${tarball}.json`, 'utf8'));
const pkg = JSON.parse(readFileSync('packages/lyra-ui/package.json', 'utf8'));
const bytes = readFileSync(tarball);
assert.equal(receipt.name, pkg.name);
assert.equal(receipt.version, pkg.version);
assert.equal(receipt.fileName, basename(tarball));
assert.equal(receipt.packedBytes, bytes.length);
assert.equal(receipt.sha256, createHash('sha256').update(bytes).digest('hex'));
NODE
node scripts/check-peer-compatibility.mjs --tarball "${tarballs[0]}"

sudo tee /etc/apt/apt.conf.d/99-lyra-ci >/dev/null <<'EOF'
Acquire::Retries "3";
Acquire::http::Timeout "20";
Acquire::https::Timeout "20";
EOF

node --input-type=module <<'NODE'
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
const node = readFileSync('.nvmrc', 'utf8').trim().replace(/^v/, '');
const manager = JSON.parse(readFileSync('package.json', 'utf8')).packageManager;
const pnpm = /^pnpm@(\d+\.\d+\.\d+)$/.exec(manager)?.[1];
const actualPnpm = execFileSync('pnpm', ['--version'], { encoding: 'utf8' }).trim();
if (process.versions.node !== node || !pnpm || actualPnpm !== pnpm) {
  throw new Error(`Expected Node ${node} and ${manager}; got Node ${process.versions.node} and pnpm@${actualPnpm}`);
}
NODE

node --input-type=module <<'NODE'
import { assertPreparationInputs } from './scripts/prepare-artifacts-paths.mjs';
assertPreparationInputs(process.env.PREPARATION_MODE, process.env.PUBLICATION_JSON, process.env.SOURCE_CONTRACTS_JSON, process.env.UPGRADE_DEPENDENCIES);
NODE
node --test scripts/prepare-artifacts.test.mjs
